<style>

/* =========================================================
   MEDIA PAGE
   ========================================================= */

.media-intro {
  max-width: 850px;
  margin: 0 auto 2.5rem auto;
  text-align: center;
  font-size: 1.05rem;
  line-height: 1.6;
}


/* YEAR HEADINGS */

.media-year {
  margin-top: 3.2rem;
  margin-bottom: 1.1rem;
  padding-bottom: 0.35rem;
  border-bottom: 1px solid rgba(128, 128, 128, 0.35);
  font-size: 1.8rem;
  font-weight: 600;
}


/* =========================================================
   GALLERY GRID
   ========================================================= */

.gallery {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 2rem;
}


/* =========================================================
   INDIVIDUAL IMAGE CARD
   ========================================================= */

.gallery-item {
  position: relative;
  overflow: hidden;
  border-radius: 7px;
  background: #111;
  aspect-ratio: 4 / 3;
  cursor: default;
}


/* IMAGE */

.gallery-item img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;

  /* Smooth hover effect */
  transition:
    transform 0.35s ease,
    filter 0.35s ease;
}


/* Slight zoom when hovering */

.gallery-item:hover img {
  transform: scale(1.04);
  filter: brightness(0.45);
}


/* =========================================================
   CAPTION OVERLAY
   ========================================================= */

.gallery-caption {
  position: absolute;
  inset: 0;

  display: flex;
  flex-direction: column;
  justify-content: flex-end;

  padding: 1rem;

  color: white;

  background:
    linear-gradient(
      to top,
      rgba(0, 0, 0, 0.90) 0%,
      rgba(0, 0, 0, 0.65) 45%,
      rgba(0, 0, 0, 0.15) 100%
    );

  opacity: 0;
  transition: opacity 0.3s ease;
}


/* Show caption on hover */

.gallery-item:hover .gallery-caption {
  opacity: 1;
}


/* Caption heading */

.gallery-caption h3 {
  color: white;
  margin: 0 0 0.35rem 0;
  font-size: 1.05rem;
  line-height: 1.2;
  font-weight: 650;
}


/* Caption text */

.gallery-caption p {
  color: rgba(255, 255, 255, 0.94);
  margin: 0;
  font-size: 0.82rem;
  line-height: 1.35;
}


/* Photo credit */

.gallery-caption .credit {
  margin-top: 0.4rem;
  font-size: 0.72rem;
  font-style: italic;
  color: rgba(255, 255, 255, 0.72);
}


/* =========================================================
   RESPONSIVE LAYOUT
   ========================================================= */

/* Smaller laptops */
@media (max-width: 1200px) {
  .gallery {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}


/* Tablets */
@media (max-width: 800px) {
  .gallery {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}


/* Phones */
@media (max-width: 520px) {

  .gallery {
    grid-template-columns: 1fr;
  }

  /*
    Phones do not have hover, so captions remain visible.
  */

  .gallery-caption {
    opacity: 1;
    background:
      linear-gradient(
        to top,
        rgba(0, 0, 0, 0.88) 0%,
        rgba(0, 0, 0, 0.45) 55%,
        transparent 100%
      );
  }

}

/* =========================================================
   MAKE MEDIA PAGE WIDER
   ========================================================= */

/* Override Quarto's normal constrained content width */
#quarto-content,
main.content {
  max-width: none !important;
}

/* Main media content width */
main.content {
  width: 92vw !important;
  margin-left: calc(50% - 46vw) !important;
  margin-right: calc(50% - 46vw) !important;
}

/* Keep introductory text readable */
.media-intro {
  max-width: 850px;
  margin: 0 auto 2.5rem auto;
  text-align: center;
  font-size: 1.05rem;
  line-height: 1.6;
}

</style>
